ssize_t tty_write(struct tty_struct *tty, struct file *file, const unsigned char *buf, size_t nr)
{
    ssize_t ret = 0;
    int nonblocking = (file->f_flags & O_NONBLOCK);

    while (ret < (ssize_t)nr) {
        if (tty_check_job_control(tty))
            return -EIO;

        down_read(&tty->sem);

        if (tty->icanon && L_ECHO(tty)) {
            process_echoes(tty);
        }

        if (test_bit(TTY_OPOST, &tty->flags)) {
            ret = process_output_block(tty, buf + ret, nr - ret);
        } else {
            ret = do_tty_write(tty, buf + ret, nr - ret);
        }

        up_read(&tty->sem);

        if (ret < 0) {
            if (ret == -ERESTARTSYS || (nonblocking && ret == -EAGAIN)) {
                return ret;
            }
            break;
        }
    }

    return ret;
}

ssize_t tty_write(struct tty_struct *tty, struct file *file, const unsigned char *buf, size_t nr)
{
    ssize_t count = 0;
    int i;
    unsigned int c;

    for (i = 0; i < nr; i++) {
        c = buf[i];

        if (tty->driver->ops->write) {
            if (tty->driver->ops->write(tty, &c, 1) != 1) {
                if (!count)
                    return -EAGAIN;
                break;
            }
        }
        count++;
    }

    return count;
}

ssize_t tty_write(struct tty_struct *tty, struct file *file, const unsigned char *buf, size_t nr)
{
    ssize_t count = 0;
    int result;

    if (tty->flags & TTY_IO_ERROR)
        return -EIO;

    if (tty->termios.c_lflag & ECHO)
        process_echoes(tty);

    while (count < nr) {
        result = do_tty_write(tty, file, buf + count, nr - count);

        if (result <= 0) {
            if (result != -EAGAIN || (file->f_flags & O_NONBLOCK))
                break;
            wait_for_space(tty);
            continue;
        }

        count += result;
    }

    return count ? count : result;
}

ssize_t tty_write(struct tty_struct *tty, struct file *file, const unsigned char *buf, size_t nr) {
    ssize_t written = 0;
    size_t count = nr;

    if (tty_jobctl(tty))
        tty_wait_until_sent(tty, 0);

    down_read(&tty->termios_sem);

    if (tty->ldisc->ops->write) {
        while (written < count) {
            ssize_t result = tty->ldisc->ops->write(tty, buf + written, count - written);

            if (result < 0) {
                if (!written)
                    written = result;
                break;
            }

            written += result;
        }
    } else {
        written = -EINVAL;
    }

    up_read(&tty->termios_sem);

    return written;
}
